cov-callback:
// trace-pc-guard runtime: writes one byte per edge (hit or not) to $COV_OUT at exit
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
static uint8_t *hit; static uint32_t n;
static void dump(void) {
    const char *p = getenv("COV_OUT");
    if (!p || !hit) return;
    FILE *f = fopen(p, "wb"); if (!f) return;
    fwrite(hit, 1, n, f); fclose(f);
}
void __sanitizer_cov_trace_pc_guard_init(uint32_t *start, uint32_t *stop) {
    if (start == stop || *start) return;
    uint32_t base = n;
    for (uint32_t *x = start; x < stop; x++) *x = ++n;
    hit = realloc(hit, n + 1);
    for (uint32_t i = base; i <= n; i++) hit[i] = 0;
    static int reg; if (!reg) { reg = 1; atexit(dump); }
}
void __sanitizer_cov_trace_pc_guard(uint32_t *g) { if (*g) hit[*g] = 1; }
